def transform(grid):
    out=[row[:] for row in grid]
    bg=grid[0][0]
    cols=[1,4,7,10,13]
    a=[[int(grid[2*r+1][c]==0) for c in cols] for r in range(6)]
    b=[[0]*5 for _ in range(6)]
    for r in range(6):
        for c in range(5):
            n=sum(0<=rr<6 and 0<=cc<5 and a[rr][cc]
                  for rr in range(r-1,r+2) for cc in range(c-1,c+2)
                  if (rr,cc)!=(r,c))
            b[r][c]=int(n==3 or (a[r][c] and n==2))
    for r in range(6):
        for c in range(5):
            out[2*r+1][cols[c]]=0 if b[r][c] else bg
    return out
